// Does stream_filter_prepend() find a USER filter, and does ::class registration work?
class UpFilter extends php_user_filter {
    public function filter($in, $out, &$consumed, $closing): int {
        while ($b = stream_bucket_make_writeable($in)) {
            $b->data = strtoupper($b->data);
            $consumed += $b->datalen;
            stream_bucket_append($out, $b);
        }
        return PSFS_PASS_ON;
    }
}
var_dump(stream_filter_register('up.literal', 'UpFilter'));
var_dump(stream_filter_register('up.classconst', UpFilter::class));

